// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Product} from "../src/Product.sol";

contract InvMutTest is Test {
    Product c;
    function setUp() public { c = new Product(); }
    function testFuzz_property(address callerA, address callerB) public {
        vm.assume(callerA != address(0));
        vm.assume(callerB != address(0));
        vm.assume(callerA != callerB);

        vm.prank(callerA);
        address oracleA = address(c.oracle());

        vm.prank(callerB);
        address oracleB = address(c.oracle());

        assertTrue(oracleA == oracleB);
    }
}
